mapper.select:
select *from (
SELECT
a.*,
b.MACHINE_NAME
FROM
T_CD15_QUOTA_SETTING a
LEFT JOIN T_CD15_MACHINE_INFO b
ON a.MACHINE_ID = b.ID
WHERE
a.del_flag = '0'
and a.steel_strip_code = #{steelStripCode}

and a.machine_id = #{machineId}
and a.quota = #{quota}

    order by a.CREATE_TIME desc

) t

    order by ${orderStr}


where del_flag = '0'
and id != #{id}
and machine_id is null
and machine_id = #{machineId,jdbcType=DECIMAL}
and steel_strip_code is null
and steel_strip_code =
    #{steelStripCode,jdbcType=VARCHAR}
